import sys
def write_png(buf, width, height):
    import zlib, struct
    def make_chunk(type, data):
        return struct.pack('>I', len(data)) + type + data + struct.pack('>I', zlib.crc32(type + data) & 0xffffffff)

    png = b'\x89PNG\r\n\x1a\n'
    png += make_chunk(b'IHDR', struct.pack('>2I5B', width, height, 8, 2, 0, 0, 0))
    flat_data = b''
    for y in range(height):
        flat_data += b'\x00' # filter type
        for x in range(width):
            v = 255 if (x+y)%2 == 0 else 0
            flat_data += bytes([v, v, v])
    png += make_chunk(b'IDAT', zlib.compress(flat_data))
    png += make_chunk(b'IEND', b'')
    buf.write(png)

with open('test.png', 'wb') as f:
    write_png(f, 8, 8)
""}

